// Generated by vibelang from character/event.ts; the migrate flow writes it again with each batch.
const nameOf = (world, role, id) => {
    if (id === "owner")
        return world.data.owner.name;
    if (id === role)
        return "You";
    if (id === "system")
        return "System";
    return world.data.team.find((member) => member.id === id)?.name ?? id;
};
const weekday = (iso) => {
    const date = new Date(`${iso.slice(0, 10)}T12:00:00Z`);
    return date.toLocaleDateString("en-US", { weekday: "short", month: "short", day: "numeric", timeZone: "UTC" });
};
const stamp = (iso) => (iso === undefined ? "" : `[${weekday(iso)} ${iso.slice(11, 16)}] `);
/** Where the event arrived, in words. */
export const whereOf = (world, role, where) => {
    if (where === "dm")
        return `your direct messages with ${world.data.owner.name}`;
    if (where.startsWith("agent:"))
        return `a direct message from ${nameOf(world, role, where.slice(6))}`;
    if (where.startsWith("channel:")) {
        return `the #${where.slice(8)} channel (every agent and ${world.data.owner.name} can read it)`;
    }
    if (where === "event")
        return "a scheduled event (no one wrote to you; nothing is posted unless you send it)";
    return where;
};
/** Renders the turn's prompt. */
export const render = (options) => {
    const { history, role, trigger, where, world } = options;
    const now = world.data.now;
    const date = new Date(now);
    const local = `${weekday(now)} ${now.slice(0, 4)}, ${now.slice(11, 16)} (${world.data.owner.timezone})`;
    const lines = [
        `Now: ${Number.isNaN(date.getTime()) ? now : local}`,
        `Where: ${whereOf(world, role, where)}`
    ];
    if (history.length > 0) {
        lines.push("", "Earlier in this conversation:");
        for (const message of history) {
            lines.push(`${stamp(message.at)}${nameOf(world, role, message.from)}: ${message.text}`);
        }
    }
    lines.push("", trigger.from === "system" ? "Event:" : `New message from ${nameOf(world, role, trigger.from)}:`, trigger.text);
    return lines.join("\n");
};
